{
  "themes": [
    {
      "cluster": 24,
      "name": "Rude Gate Agent Behavior",
      "description": "Customers report gate agents and attendants being unhelpful, rude, or refusing assistance."
    },
    {
      "cluster": 25,
      "name": "Refund and Cancellation Confusion",
      "description": "Users are unclear about how to cancel flights, refund eligibility, and are experiencing double charges."
    },
    {
      "cluster": 26,
      "name": "Overall Poor Customer Service",
      "description": "Feedback highlights repeated failures in support, delayed responses, and lack of empathy during disruptions."
    },
    {
      "cluster": 27,
      "name": "Extended Flight Delays",
      "description": "Passengers experience long delays, diversions, and insufficient assistance while waiting."
    },
    {
      "cluster": 28,
      "name": "Positive Customer Service Praise",
      "description": "Customers express gratitude for helpful, friendly, and efficient support interactions."
    },
    {
      "cluster": 29,
      "name": "High Change Fees and Ticket Pricing",
      "description": "Users complain about expensive change fees, inflated ticket prices, and inconsistent mileage pricing."
    },
    {
      "cluster": 30,
      "name": "Flight Change Process Questions",
      "description": "Travelers seek guidance on how to modify or reschedule their flights."
    },
    {
      "cluster": 31,
      "name": "Boarding Pass Access Issues",
      "description": "Customers cannot retrieve or add boarding passes via the mobile app or wallet integration."
    },
    {
      "cluster": 32,
      "name": "Difficulty Changing Flights Online",
      "description": "Users encounter broken website/app flows and long phone hold times when trying to change reservations."
    },
    {
      "cluster": 33,
      "name": "Booking and Check‑In Failures",
      "description": "Passengers report inability to search, book, or check‑in for flights through the app or website."
    },
    {
      "cluster": 34,
      "name": "Irrelevant or Spam Content",
      "description": "Posts contain unrelated links, promotional messages, or off‑topic comments."
    },
    {
      "cluster": 35,
      "name": "Appreciation for Exceptional Service",
      "description": "Customers thank specific staff members for outstanding assistance and care."
    }
  ]
}
